e": "preprint", "cited_by_count": 0, "open_access": {"is_oa": true, "oa_status": "green", "oa_url": "https://arxiv.org/pdf/2604.17308", "any_repository_has_fulltext": true}, "primary_location": {"id": "pmh:oai:arXiv.org:2604.17308", "doi": null, "is_oa": true, "landing_page_url": "https://arxiv.org/abs/2604.17308", "pdf_url": "https://arxiv.org/pdf/2604.17308", "source": {"id": "https://openalex.org/S4306400194", "display_name": "arXiv (Cornell University)", "issn_l": "2331-8422", "issn": ["2331-8422"], "is_oa": true, "is_in_doaj": false, "is_core": false, "listed_in": [], "host_organization": "https://openalex.org/I205783295", "host_organization_name": "Cornell University", "host_organization_lineage": ["https://openalex.org/I205783295"], "host_organization_lineage_names": [], "type": "repository"}, "license": "cc-by", "license_id": "https://openalex.org/licenses/cc-by", "version": "submittedVersion", "is_accepted": false, "is_published": false, "raw_source_name": null, "raw_type": "text"}, "abstract": "As the capability frontier of autonomous agents continues to expand, they are increasingly able to complete specialized tasks through plug-and-play external skills. Yet current benchmarks mostly test whether models can use provided skills, leaving open whether they can discover skills from experience, repair them after failure, and maintain a coherent library over time. We introduce SkillFlow, a benchmark of 166 tasks across 20 families in which task construction within each family follows a Domain-Agnostic Execution Flow (DAEF) that defines an agent workflow framework, allowing these tasks to share a consistent workflow. Agents are evaluated under an Agentic Lifelong Learning protocol in which they begin without skills, solve tasks sequentially within each family, externalize lessons through trajectory- and rubric-driven skill patches, and carry the updated library forward. Experiments reveal a substantial capability gap. For Claude Opus 4.6, lifelong skill evolution improves task success from 62.65% to 71.08% (+8.43 points). However, high skill usage does not necessarily imply high utility: Kimi K2.5 gains only +0.60 points despite 66.87% skill usage, while Qwen-Coder-Next reaches only a 44.58% task completion rate and still regresses relative to the vanilla setting. SkillFlow contributes a structured testbed for this direction and an in-depth empirical analysis of skill discovery, patching, transfer, and their failure modes under lifelong evaluation."}]", "excerpt_truncated": true, "source_sha256": "36e9ba8001ce8954a168b7fd4705a673bfd66fde225d7099150c6db9c94dde52", "verification_required": true, "topic_domain": "emergent_preferences", "evidence_role": "discovery", "host_tier": "discovery", "source_identity": null, "persistent_identifiers": ["doi:10.1007/s11704-024-40231-1", "doi:10.1007/s11704-024-40231-1.pdf", "openalex:W1556756526", "openalex:W4393065402", "arxiv:2604.17308"], "source_candidates": ["https://era.ed.ac.uk/bitstreams/0d89c220-ac61-43c2-88e5-f7ec9766a400/download", "https://doi.org/10.1007/s11704-024-40231-1", "https://link.springer.com/content/pdf/10.1007/s11704-024-40231-1.pdf", "https://arxiv.org/pdf/2604.17308", "https://arxiv.org/abs/2604.17308"], "source_candidate_identities": {}}

